    ht_font_row(hl, 2, 7);
    ht_font_row(hl, 3, 7);
    ht_font_row(hl, 1, 8);
    ht_font_row(hl, 2, 8);
    // font 7: 10 groups on page 1 (1 agrees), 9 on page 2 (0), 2 on page 3 (0: too few); font 8 is good
    ht_groups(cg, refs, 1, pl_ea_fw(), p1, 10, 1);
    ht_groups(cg, refs, 2, pl_ea_fw(), p2, 9, 0);
    ht_groups(cg, refs, 3, pl_ea_fw(), p3, 2, 0);
