    crate::testport::assert_eq(ht_agreement_of(hl, 1, 7), 100, "pages with their own groups keep theirs");
    crate::testport::assert_eq(fe_get(feats, p3, xt_font_health()), ht_score_of(hl, 3, 7), "its word's column 13");
    crate::testport::assert_that(ht_score_of(hl, 1, 8) >= th_trusted(), "the other font is untouched");
