pub(crate) fn ht_ocr_word(mut ow: &mut crate::port::Cells, mut feats: &mut crate::port::Cells, length: i32, ink: i32, implausible: i32, body: i32, seal: i32, artifact: i32) -> i32 {
    // An OCR word whose feature row has these columns (-1 leaves one absent) and an engine confidence of 0, which means nothing.
    let w: i32 = ow_new(ow, 1, 0, 0, 1000, 1000, 0, 900, 1000, 900, 0, 0, 0, length, -1, 0, -1);
    let f: i32 = fe_new(feats, ea_owords(), w);
    ow_set(ow, w, hd_feat(), f);
    fe_set(feats, f, xo_conf(), 0);
    fe_set(feats, f, xo_length(), length);
    fe_set(feats, f, xo_kin_ink(), ink);
    fe_set(feats, f, xo_implausible(), implausible);
    fe_set(feats, f, xo_body_share(), body);
    fe_set(feats, f, xo_seal(), seal);
    fe_set(feats, f, xo_artifact(), artifact);
    return f;
}
pub(crate) fn ht_block(mut ob: &mut crate::port::Cells, mut ol: &mut crate::port::Cells, first_word: i32, nwords: i32) -> i32 {
    // A block of one paragraph of one line over `nwords` words from `first-word`; answers the block's row.
    let line: i32 = ol_new(ol, 1, 0, 0, 1000, 1000, 0, 900, 1000, 900, 0, 0, first_word, nwords);
    let b: i32 = ob_new(ob, 1, 0, 0, 1000, 1000, ob_block(), -1, 0);
    let p: i32 = ob_new(ob, 1, 0, 0, 1000, 1000, ob_paragraph(), b, 0);
    ob_set(ob, b, obf_first(), p);
    ob_set(ob, b, obf_count(), 1);
    ob_set(ob, p, obf_first(), line);
    ob_set(ob, p, obf_count(), 1);
    return b;
}
pub(crate) fn ht_block_score(hl: &mut crate::port::Cells, b: i32) -> i32 {
    let n: i32 = hl_count(hl);
    let mut i: i32 = 0;
    while i < n {
        if (hl_get(hl, i, 0) == plh_ocr_block()) && (hl_get(hl, i, 2) == b) {
            return i;
        }
        i += 1;
    }
    return -1;
}
pub(crate) fn ht_bget(hl: &mut crate::port::Cells, b: i32, field: i32) -> i32 {
    // Cell `field` of the health row of OCR block `b`.
    let r: i32 = ht_block_score(hl, b);
    return hl_get(hl, r, field);
}
#[test]
fn test_ocr_blocks() {
    let words: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let fw: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let feats: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let cg: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let refs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let hl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ob: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ol: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ow: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    // block 0: body text (ink 150, nothing implausible, 95 % on the body layer, no seal, no artifact); 1: over blank paper;
    // 2: under a seal; 3: soup; 4: watermark (artifact 900, light ink); 5: no ink columns at all, only the plausibility
    ht_ocr_word(ow, feats, 5, 150, 0, 950, 0, 0);
    ht_ocr_word(ow, feats, 6, 140, 0, 960, 0, 0);
    ht_block(ob, ol, 0, 2);
    ht_ocr_word(ow, feats, 6, 2, 0, 0, 0, 0);
    ht_block(ob, ol, 2, 1);
    ht_ocr_word(ow, feats, 6, 150, 0, 100, 900, 0);
    ht_block(ob, ol, 3, 1);
    ht_ocr_word(ow, feats, 6, 150, 800, 950, 0, 0);
    ht_block(ob, ol, 4, 1);
    ht_ocr_word(ow, feats, 6, 40, 0, 100, 0, 900);
    ht_block(ob, ol, 5, 1);
    ht_ocr_word(ow, feats, 6, -1, 0, -1, -1, -1);
    ht_block(ob, ol, 6, 1);
    crate::testport::assert_eq(hl_page(1, cg, refs, fw, words, et, feats, ob, ol, ow, hl), 6, "six blocks scored");
    crate::testport::assert_eq(hl_count(hl), 6, "and six rows");
    let body: i32 = ht_bget(hl, 0, hlf_score());
    let blank: i32 = ht_bget(hl, 2, hlf_score());
    let seal: i32 = ht_bget(hl, 4, hlf_score());
    let soup: i32 = ht_bget(hl, 6, hlf_score());
    let mark: i32 = ht_bget(hl, 8, hlf_score());
    let bare: i32 = ht_bget(hl, 10, hlf_score());
    crate::testport::assert_that(body >= 900, "a body block is trusted");
    crate::testport::assert_that(blank < body, "blank paper scores under the body");
    crate::testport::assert_that(seal < body, "a seal scores under the body");
    crate::testport::assert_that(soup < body, "soup scores under the body");
    crate::testport::assert_that(mark < body, "a watermark scores under the body");
    crate::testport::assert_that(blank < 300, "blank paper is far under");
    crate::testport::assert_that(seal < 300, "a seal is far under");
    crate::testport::assert_eq(bare, 1000, "a block with only a plausibility is scored on it: what is absent does not drag");
    crate::testport::assert_eq(ht_bget(hl, 0, hob_seal()), 1000, "the body's seal component: 1000 - 0");
    crate::testport::assert_eq(ht_bget(hl, 4, hob_seal()), 100, "the seal block's: 1000 - 900");
    crate::testport::assert_eq(ht_bget(hl, 4, hob_body()), 100, "and its body share");
    crate::testport::assert_eq(ht_bget(hl, 8, hob_artifact()), 100, "the watermark's artifact component");
    crate::testport::assert_eq(ht_bget(hl, 10, hob_ink()), -1, "an absent column is -1");
    crate::testport::assert_eq(ht_bget(hl, 10, hob_seal()), -1, "and stays absent");
    crate::testport::assert_eq(ht_bget(hl, 10, hob_plausible()), 1000, "while the plausibility is there");
    crate::testport::assert_eq(ht_bget(hl, 0, hob_script()), -1, "no script column: ignored");
    crate::testport::assert_eq(ht_bget(hl, 0, hob_plausible()), 1000, "the body's plausibility");
    crate::testport::assert_eq(ht_bget(hl, 0, hob_ink()), 1000, "the body's ink support: 150 is over `ink-ok`");
    crate::testport::assert_eq(ht_bget(hl, 2, hob_ink()), 0, "blank paper's: 2 is under `ink-bad`");
    // a second call overwrites
    hl_page(1, cg, refs, fw, words, et, feats, ob, ol, ow, hl);
    crate::testport::assert_eq(hl_count(hl), 6, "no row is added");
}
pub(crate) fn ht_rule(mut rl: &mut crate::port::Cells, page: i32, x0: i32, y0: i32, x1: i32, y1: i32, conf: i32) -> i32 {
    let r: i32 = rl_new(rl, page, x0 - 0, y0 - 0, x1, y1, 0);
    rl_set(rl, r, 6, x0);
    rl_set(rl, r, 7, y0);
    rl_set(rl, r, 8, x1);
    rl_set(rl, r, 9, y1);
    rl_set(rl, r, rlf_conf(), conf);
    return r;
}
#[test]
fn test_regions() {
    let hl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let im: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    // an image placement of 10 x 10 cm at (10000, 10000); a page of rules outside it, parallel to the axes within 10 centi-degrees
    im_new(im, 1, 10000, 10000, 20000, 20000, 5, 800, 800);
    ht_rule(rl, 1, 1000, 1000, 50000, 1000, 900);
    ht_rule(rl, 1, 1000, 5000, 50000, 5003, 950);
    ht_rule(rl, 1, 1000, 1000, 1000, 40000, 850);
    // inside the image: skewed 1.5 degrees, far from parallel to each other
    ht_rule(rl, 1, 11000, 12000, 19000, 12100, 700);
    ht_rule(rl, 1, 11000, 15000, 19000, 15000, 700);
    ht_rule(rl, 1, 12000, 11000, 12150, 19000, 600);
    crate::testport::assert_eq(hl_regions(1, im, rl, 920, 960, hl), 2, "R0 and one image");
    crate::testport::assert_eq(hl_get(hl, 0, 2), -1, "R0's subject");
    crate::testport::assert_eq(hl_get(hl, 0, hrg_rules()), 3, "three rules outside the image");
    crate::testport::assert_eq(hl_get(hl, 0, hrg_witness()), 920, "the witness is the caller's");
    crate::testport::assert_eq(hl_get(hl, 0, hrg_precision()), 960, "and so is the precision");
    crate::testport::assert_eq(hl_get(hl, 0, hrg_conf()), 900, "the mean confidence of 900, 950, 850");
    crate::testport::assert_that(hl_get(hl, 0, hrg_skew()) >= 900, "parallel rules: the skew component is high");
    crate::testport::assert_that(hl_get(hl, 0, hlf_score()) >= 800, "R0's score is high");
    crate::testport::assert_eq(hl_get(hl, 1, 2), 0, "the image's subject is its row");
    crate::testport::assert_eq(hl_get(hl, 1, hrg_rules()), 3, "three rules inside it");
    crate::testport::assert_eq(hl_get(hl, 1, hrg_witness()), -1, "no witness of its own");
    crate::testport::assert_eq(hl_get(hl, 1, hrg_precision()), 960, "it borrows the page's precision");
    crate::testport::assert_eq(hl_get(hl, 1, hrg_conf()), 666, "the mean of 700, 700, 600");
    crate::testport::assert_that(hl_get(hl, 1, hrg_skew()) < 1000, "a spread over 30 centi-degrees costs");
    crate::testport::assert_that(hl_get(hl, 1, hlf_score()) < hl_get(hl, 0, hlf_score()), "the image scores under R0");
    // again: overwritten
    hl_regions(1, im, rl, 920, 960, hl);
    crate::testport::assert_eq(hl_count(hl), 2, "no row is added");
}
#[test]
fn test_the_tracers_symbol_support_joins_the_ink_support() {
    let feats: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ow: &mut crate::port::Cells = &mut crate::port::Cells::new();
    // ink 150 is full support alone; with the tracer saying none of the symbols has a text-like component it is half
    ht_ocr_word(ow, feats, 5, 150, 0, 1000, 0, 0);
    ht_ocr_word(ow, feats, 5, 150, 0, 1000, 0, 0);
    fe_set(feats, 1, xo_comp_ratio(), 0);
    ht_ocr_word(ow, feats, 5, -1, 0, 1000, 0, 0);
    fe_set(feats, 2, xo_comp_ratio(), 400);
    crate::testport::assert_eq(hh_word_score(feats, 0), 1000, "the word with ink alone");
    crate::testport::assert_that(hh_word_score(feats, 1) < hh_word_score(feats, 0), "the same word with no component in its symbols scores under it");
    crate::testport::assert_eq(hh_word_score(feats, 2), 529, "a word with only the tracer's share is scored on it: 14e6 / 18500 = 756, times 1400 / 2000");
    crate::testport::assert_eq(hh_word_score(feats, -1), -1, "no feature row: no score");
}
